mapper.select:
SELECT quest_eng_name, quest_kor_name, quest_count, quest_day_type, quest_reward, quest_reward_count
FROM quest_data

where quest_eng_name = #{quest_eng_name}

SELECT clear_quest_name, quest_day_type, ins_date
FROM quest_log
WHERE user_uuid = #{user_uuid}
  AND quest_day_type = 'day'
  AND DATE(ins_date) = CURDATE();

SELECT COUNT(*) as adReward_quest
FROM quest_log
WHERE user_uuid = #{user_uuid}
  AND clear_quest_name = #{clear_quest_name}
  AND DATE(ins_date) = CURDATE()

SELECT COUNT(*)
FROM quest_log
WHERE user_uuid = #{user_uuid}
    AND clear_quest_name = #{clear_quest_name}

    AND DATE(ins_date) = CURDATE()


    AND DATE(ins_date) BETWEEN (SELECT ADDDATE(CURDATE(), - WEEKDAY(CURDATE()) + 0 )) AND (SELECT ADDDATE(CURDATE(), - WEEKDAY(CURDATE()) + 6 ))

