UPDATE user_day_quest_data
SET
    epic_skill_upgrade_count = epic_skill_upgrade_count + #{epic_skill_upgrade_count}
WHERE user_uuid = #{user_uuid}
  AND quest_date = DATE_FORMAT(NOW(), '%Y-%m-%d 00:00:00')
